"use client";

import { GlassLink, GlassButton } from "./glass-surface";
/* Saved image URLs are generated by our server and preserve transparent pixels. */
/* eslint-disable @next/next/no-img-element */
import GlassSurface from "./glass-surface";
import { useCallback, useEffect, useState } from "react";
import { api, type LibraryAsset, type RequestView } from "./workshop-api";
import { ASSET_CATEGORIES, CATEGORY_KO } from "../lib/server/workshop/types";

export function PngDownloads({ asset }: { asset: LibraryAsset }) {
  const views =
    asset.appearance.kind === "texture"
      ? [["texture", "바닥 그림"]]
      : [
          ["td", "위에서 본 그림"],
          ["iso", "입체 그림"],
        ].concat(
          asset.appearance.sprites
            ? [
                ["td-sprite", "위에서 본 동작"],
                ["iso-sprite", "입체 동작"],
              ]
            : [],
        );
  return (
    <div className="asset-downloads">
      {views.map(([view, label]) => (
        <GlassLink
          className="btn sm"
          key={view}
          href={`/api/jamworld/workshop/catalog/${encodeURIComponent(asset.id)}/download?view=${view}`}
          download
        >
          {label} ↓
        </GlassLink>
      ))}
    </div>
  );
}

export default function AssetLibrary({ mine = false, onRemade }: { mine?: boolean; onRemade?: (request: RequestView) => void }) {
  const [assets, setAssets] = useState<LibraryAsset[] | null>(null);
  const [canManage, setCanManage] = useState(false);
  const [error, setError] = useState("");
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("all");
  const [removing, setRemoving] = useState("");
  const [remaking, setRemaking] = useState("");
  const reload = useCallback(async () => {
    try {
      const catalog = await api<{ assets: LibraryAsset[]; canManage: boolean }>(
        "/api/jamworld/workshop/catalog",
      );
      const list = mine
        ? (
            await api<{ assets: LibraryAsset[] }>(
              "/api/jamworld/workshop/library",
            )
          ).assets
        : catalog.assets;
      setAssets(list);
      setCanManage(catalog.canManage);
      setError("");
    } catch (e) {
      setError(e instanceof Error ? e.message : "에셋을 불러오지 못했어요.");
    }
  }, [mine]);
  useEffect(() => {
    void Promise.resolve().then(reload);
    const focus = () => void reload();
    window.addEventListener("focus", focus);
    return () => window.removeEventListener("focus", focus);
  }, [reload]);
  async function remove(asset: LibraryAsset) {
    if (
      !window.confirm(
        `‘${asset.name}’ 에셋을 삭제할까요? 공용 목록과 보관함에서 더 이상 선택할 수 없어요.`,
      )
    )
      return;
    setRemoving(asset.id);
    try {
      await api(`/api/jamworld/workshop/catalog/${asset.id}`, {
        method: "DELETE",
      });
      await reload();
      window.dispatchEvent(new Event("jamworld-assets"));
    } catch (e) {
      setError(e instanceof Error ? e.message : "삭제하지 못했어요.");
    } finally {
      setRemoving("");
    }
  }
  const text = query.trim().toLowerCase();
  const shown = (assets ?? []).filter(
    (a) =>
      (category === "all" || a.category === category) &&
      (!text || `${a.name} ${a.tags.join(" ")}`.toLowerCase().includes(text)),
  );
  return (
    <section className="card ws-pad asset-library">
      <div className="section-title">
        <div>
          <h2>{mine ? "내가 만든 에셋" : "함께 만든 에셋"}</h2>
        </div>
        <GlassButton className="btn sm" onClick={() => void reload()}>
          새로고침
        </GlassButton>
      </div>
      <p className="ws-note">
        마음에 드는 그림을 월드에 놓거나 내려받아 보세요.
      </p>
      <div className="asset-filters">
        <label>
          <span className="sr-only">에셋 분류</span>
          <select
            className="select"
            value={category}
            onChange={(e) => setCategory(e.target.value)}
          >
            <option value="all">전체 분류</option>
            {ASSET_CATEGORIES.map((c) => (
              <option value={c} key={c}>
                {CATEGORY_KO[c]}
              </option>
            ))}
          </select>
        </label>
        <label>
          <span className="sr-only">이름·태그 검색</span>
          <input
            className="input"
            placeholder="이름·태그 검색"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
        </label>
        <span className="chip">{shown.length}개</span>
        {canManage && <span className="chip">관리자</span>}
      </div>
      {error && (
        <p className="issue err" role="alert">
          {error}
        </p>
      )}
      {!assets && !error && <p role="status">에셋을 불러오고 있어요…</p>}
      {assets && !shown.length && (
        <div className="empty">
          {query || category !== "all"
            ? "조건에 맞는 에셋이 없어요."
            : "아직 저장한 에셋이 없어요. 공방에서 첫 에셋을 만들어 보세요."}
        </div>
      )}
      <div className="grid-cards">
        {shown.map((a) => (
          <GlassSurface
            key={a.id}
            className="card asset-tile"
            contentClassName="asset-tile-content"
            frost={0.06}
            data-asset-id={a.id}
          >
            <div className="card-thumb ws-lib-thumb">
              <img
                src={a.urls.td || a.urls.texture || ""}
                alt={a.name}
                loading="lazy"
              />
            </div>
            <div className="card-body">
              <h3>{a.name}</h3>
              <p>
                {CATEGORY_KO[a.category]} · {a.behavior.footprint.w}×
                {a.behavior.footprint.d}칸
              </p>
              <div className="row">
                {a.tags.map((tag) => (
                  <span className="chip" key={tag}>
                    {tag}
                  </span>
                ))}
              </div>
              <PngDownloads asset={a} />
              {a.category === "character" && <GlassLink className="btn sm primary asset-avatar" href={`/jamworldmake/?view=profile&asset=${encodeURIComponent(a.id)}`}>내 아바타로 고르기</GlassLink>}
              {onRemade && a.category === "character" && a.appearance.kind === "views" && !a.appearance.sprites && <GlassButton className="btn sm" disabled={!!remaking} onClick={async () => {
                setRemaking(a.id);
                try {
                  const value = await api<{ request: RequestView }>("/api/jamworld/workshop/requests", { method: "POST", json: { sourceAssetId: a.id } });
                  onRemade(value.request);
                } catch (e) { setError(e instanceof Error ? e.message : "초안을 만들지 못했어요"); }
                finally { setRemaking(""); }
              }}>{remaking === a.id ? "초안 만드는 중…" : "걷는 아바타로 만들기"}</GlassButton>}
              {canManage && (
                <GlassButton
                  className="btn sm asset-remove"
                  disabled={!!removing}
                  onClick={() => void remove(a)}
                >
                  {removing === a.id ? "삭제 중…" : "에셋 삭제"}
                </GlassButton>
              )}
            </div>
          </GlassSurface>
        ))}
      </div>
    </section>
  );
}
